CREATE TABLE IF NOT EXISTS app_users(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','user')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS budgets(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,amount NUMERIC(12,2) NOT NULL CHECK(amount>=0),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS transactions(id BIGSERIAL PRIMARY KEY,transaction_date DATE NOT NULL DEFAULT CURRENT_DATE,type TEXT NOT NULL CHECK(type IN('Donation','Expense')),person TEXT NOT NULL,amount NUMERIC(12,2) NOT NULL CHECK(amount>0),payment_mode TEXT NOT NULL DEFAULT 'Cash',reference_id TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',created_by BIGINT REFERENCES app_users(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS transactions_date_idx ON transactions(transaction_date DESC);
